INSERT INTO `document_templates` VALUES (1,NULL,'Modern Invoice','invoice',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <title>Invoice</title>\r\n    <style>\r\n        body { font-family: \'Helvetica Neue\', \'Helvetica\', Helvetica, Arial, sans-serif; color: #555; }\r\n        .invoice-box { max-width: 800px; margin: auto; padding: 30px; border: 1px solid #eee; box-shadow: 0 0 10px rgba(0, 0, 0, .15); font-size: 16px; line-height: 24px; color: #555; }\r\n        .invoice-box table { width: 100%; line-height: inherit; text-align: left; }\r\n        .invoice-box table td { padding: 5px; vertical-align: top; }\r\n        .invoice-box table tr td:nth-child(2) { text-align: right; }\r\n        .header { background: #f8f9fa; border-bottom: 2px solid #333; }\r\n        .heading td { background: #333; color: #fff; font-weight: bold; }\r\n        .total td { border-top: 2px solid #eee; font-weight: bold; }\r\n        .text-right { text-align: right; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"invoice-box\">\r\n        <table cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr class=\"top\">\r\n                <td colspan=\"2\">\r\n                    <table>\r\n                        <tr>\r\n                            <td class=\"title\">\r\n                                <h1 style=\"margin: 0;\">INVOICE</h1>\r\n                                <span style=\"font-size: 14px; color: #888;\">#{{ $number }}</span>\r\n                            </td>\r\n                            <td>\r\n                                <strong>{{ $tenant->company_name }}</strong><br>\r\n                                {{ $tenant->address }}<br>\r\n                                {{ $tenant->email }}\r\n                            </td>\r\n                        </tr>\r\n                    </table>\r\n                </td>\r\n            </tr>\r\n            <tr class=\"information\">\r\n                <td colspan=\"2\">\r\n                    <table>\r\n                        <tr>\r\n                            <td>\r\n                                <strong>Tagihan Ke:</strong><br>\r\n                                {{ $client->name }}<br>\r\n                                {{ $client->address }}\r\n                            </td>\r\n                            <td class=\"text-right\">\r\n                                <strong>Tanggal:</strong> {{ $date }}<br>\r\n                                <strong>Jatuh Tempo:</strong> {{ $due_date }}\r\n                            </td>\r\n                        </tr>\r\n                    </table>\r\n                </td>\r\n            </tr>\r\n            <tr class=\"heading\">\r\n                <td>Item</td>\r\n                <td class=\"text-right\">Harga</td>\r\n            </tr>\r\n            @foreach($items as $item)\r\n            <tr class=\"item\">\r\n                <td>{{ $item->description }} <br><small>x{{ $item->quantity }} {{ $item->unit }}</small></td>\r\n                <td class=\"text-right\">{{ format_currency($item->total) }}</td>\r\n            </tr>\r\n            @endforeach\r\n            <tr class=\"total\">\r\n                <td></td>\r\n                <td class=\"text-right\">Total: {{ format_currency($total) }}</td>\r\n            </tr>\r\n        </table>\r\n    </div>\r\n</body>\r\n</html>',NULL,1,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(2,NULL,'Classic Invoice','invoice',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <title>Invoice</title>\r\n    <style>\r\n        body { font-family: \'Times New Roman\', Times, serif; color: #333; }\r\n        .invoice-box { max-width: 800px; margin: auto; padding: 30px; border: 1px solid #999; }\r\n        .header { text-align: center; margin-bottom: 40px; }\r\n        .header h1 { margin: 0; font-size: 36px; text-transform: uppercase; letter-spacing: 2px; }\r\n        .meta { margin-bottom: 30px; width: 100%; }\r\n        .meta td { vertical-align: top; width: 50%; }\r\n        .items { width: 100%; border-collapse: collapse; margin-bottom: 30px; }\r\n        .items th, .items td { border: 1px solid #999; padding: 8px; }\r\n        .items th { background: #eee; text-align: left; }\r\n        .totals { width: 100%; text-align: right; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"invoice-box\">\r\n        <div class=\"header\">\r\n            <h1>INVOICE</h1>\r\n            <p>{{ $tenant->company_name }}</p>\r\n        </div>\r\n        <table class=\"meta\">\r\n            <tr>\r\n                <td>\r\n                    <strong>Kepada:</strong><br>\r\n                    {{ $client->name }}<br>\r\n                    {{ $client->address }}\r\n                </td>\r\n                <td style=\"text-align: right;\">\r\n                    <strong>No. Invoice:</strong> {{ $number }}<br>\r\n                    <strong>Tanggal:</strong> {{ $date }}<br>\r\n                    <strong>Jatuh Tempo:</strong> {{ $due_date }}\r\n                </td>\r\n            </tr>\r\n        </table>\r\n        <table class=\"items\">\r\n            <thead>\r\n                <tr>\r\n                    <th>Deskripsi</th>\r\n                    <th style=\"width: 80px;\">Qty</th>\r\n                    <th style=\"width: 120px;\">Harga Satuan</th>\r\n                    <th style=\"width: 120px;\">Total</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                @foreach($items as $item)\r\n                <tr>\r\n                    <td>{{ $item->description }}</td>\r\n                    <td>{{ $item->quantity }}</td>\r\n                    <td>{{ format_currency($item->price) }}</td>\r\n                    <td>{{ format_currency($item->total) }}</td>\r\n                </tr>\r\n                @endforeach\r\n            </tbody>\r\n        </table>\r\n        <div class=\"totals\">\r\n            <h3>Total: {{ format_currency($total) }}</h3>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(3,NULL,'Bold Invoice','invoice',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <title>Invoice</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; color: #000; }\r\n        .invoice-box { max-width: 800px; margin: auto; }\r\n        .header { background: #000; color: #fff; padding: 40px; }\r\n        .header h1 { margin: 0; font-size: 40px; }\r\n        .content { padding: 40px; }\r\n        .items { width: 100%; border-collapse: collapse; margin-top: 30px; }\r\n        .items th { border-bottom: 4px solid #000; padding: 10px; text-align: left; }\r\n        .items td { border-bottom: 1px solid #ddd; padding: 10px; }\r\n        .total { margin-top: 30px; text-align: right; font-size: 24px; font-weight: bold; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"invoice-box\">\r\n        <div class=\"header\">\r\n            <table width=\"100%\">\r\n                <tr>\r\n                    <td>\r\n                        <h1>INVOICE</h1>\r\n                        <p>#{{ $number }}</p>\r\n                    </td>\r\n                    <td align=\"right\">\r\n                        {{ $tenant->company_name }}<br>\r\n                        {{ $tenant->email }}\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </div>\r\n        <div class=\"content\">\r\n            <p><strong>Ditujukan Kepada:</strong><br>\r\n            {{ $client->name }}<br>\r\n            {{ $client->address }}</p>\r\n            \r\n            <table class=\"items\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>Deskripsi</th>\r\n                        <th>Jumlah</th>\r\n                        <th>Harga</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    @foreach($items as $item)\r\n                    <tr>\r\n                        <td>{{ $item->description }}</td>\r\n                        <td>{{ $item->quantity }}</td>\r\n                        <td>{{ format_currency($item->total) }}</td>\r\n                    </tr>\r\n                    @endforeach\r\n                </tbody>\r\n            </table>\r\n            \r\n            <div class=\"total\">\r\n                Total Pembayaran: {{ format_currency($total) }}\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(4,NULL,'Corporate Quotation','quotation',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <title>Penawaran</title>\r\n    <style>\r\n        body { font-family: \'Helvetica Neue\', Helvetica, Arial, sans-serif; }\r\n        .container { max-width: 800px; margin: auto; padding: 30px; }\r\n        .header { border-bottom: 2px solid #2c3e50; padding-bottom: 20px; margin-bottom: 30px; }\r\n        .title { color: #2c3e50; font-size: 28px; font-weight: bold; }\r\n        .items-table { width: 100%; border-collapse: collapse; }\r\n        .items-table th { background: #2c3e50; color: white; padding: 10px; text-align: left; }\r\n        .items-table td { border-bottom: 1px solid #ecf0f1; padding: 10px; }\r\n        .footer { margin-top: 50px; text-align: center; font-size: 12px; color: #7f8c8d; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <table width=\"100%\">\r\n                <tr>\r\n                    <td class=\"title\">PENAWARAN HARGA</td>\r\n                    <td align=\"right\">\r\n                        <strong>{{ $tenant->company_name }}</strong><br>\r\n                        {{ $date }}\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </div>\r\n        <p>Kepada Yth,<br><strong>{{ $client->name }}</strong></p>\r\n        <p>Dengan hormat,<br>Berikut kami sampaikan penawaran harga:</p>\r\n        \r\n        <table class=\"items-table\">\r\n            <thead>\r\n                <tr>\r\n                    <th>Deskripsi</th>\r\n                    <th>Qty</th>\r\n                    <th>Harga</th>\r\n                    <th>Subtotal</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                @foreach($items as $item)\r\n                <tr>\r\n                    <td>{{ $item->description }}</td>\r\n                    <td>{{ $item->quantity }}</td>\r\n                    <td>{{ format_currency($item->price) }}</td>\r\n                    <td>{{ format_currency($item->total) }}</td>\r\n                </tr>\r\n                @endforeach\r\n            </tbody>\r\n        </table>\r\n        \r\n        <div style=\"text-align: right; margin-top: 20px;\">\r\n            <h3>Total Estimasi: {{ format_currency($total) }}</h3>\r\n        </div>\r\n\r\n        <div class=\"footer\">\r\n            Penawaran ini berlaku hingga {{ $valid_until }}. Terima kasih atas kerjasamanya.\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>',NULL,1,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(5,NULL,'Simple Quotation','quotation',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <title>Quotation</title>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; font-size: 14px; }\r\n        .box { border: 1px solid #ccc; padding: 20px; }\r\n        .title { font-size: 24px; font-weight: bold; margin-bottom: 20px; }\r\n        table { width: 100%; border-collapse: collapse; margin-top: 20px; }\r\n        th, td { border: 1px solid #eee; padding: 8px; text-align: left; }\r\n        th { background: #f9f9f9; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"box\">\r\n        <div class=\"title\">QUOTATION #{{ $number }}</div>\r\n        <div>\r\n            Dari: {{ $tenant->company_name }}<br>\r\n            Untuk: {{ $client->name }}\r\n        </div>\r\n        <table>\r\n            <thead>\r\n                <tr>\r\n                    <th>Item</th>\r\n                    <th>Qty</th>\r\n                    <th>Harga</th>\r\n                    <th>Jumlah</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                @foreach($items as $item)\r\n                <tr>\r\n                    <td>{{ $item->description }}</td>\r\n                    <td>{{ $item->quantity }}</td>\r\n                    <td>{{ format_currency($item->price) }}</td>\r\n                    <td>{{ format_currency($item->total) }}</td>\r\n                </tr>\r\n                @endforeach\r\n            </tbody>\r\n            <tfoot>\r\n                <tr>\r\n                    <td colspan=\"3\" align=\"right\"><strong>Valid Hingga {{ $valid_until }}</strong></td>\r\n                    <td><strong>{{ format_currency($total) }}</strong></td>\r\n                </tr>\r\n            </tfoot>\r\n        </table>\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(6,NULL,'Creative Quotation','quotation',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <title>Quotation</title>\r\n    <style>\r\n        body { font-family: \'Trebuchet MS\', sans-serif; color: #444; }\r\n        .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; border-radius: 10px 10px 0 0; }\r\n        .body { background: white; padding: 30px; border: 1px solid #ddd; border-top: none; border-radius: 0 0 10px 10px; }\r\n        h1 { margin: 0; }\r\n        .item-row { border-bottom: 1px solid #eee; padding: 10px 0; display: flex; justify-content: space-between; }\r\n        .total-row { background: #f4f7fa; padding: 15px; margin-top: 20px; border-radius: 8px; text-align: right; font-weight: bold; color: #333; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div style=\"max-width: 800px; margin: auto;\">\r\n        <div class=\"header\">\r\n            <table width=\"100%\">\r\n                <tr>\r\n                    <td>\r\n                        <h1>Hi, {{ $client->name }}</h1>\r\n                        <p>Berikut adalah penawaran spesial untuk Anda.</p>\r\n                    </td>\r\n                    <td align=\"right\">\r\n                        <h2>{{ $number }}</h2>\r\n                        <small>{{ $date }}</small>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </div>\r\n        <div class=\"body\">\r\n            @foreach($items as $item)\r\n            <div class=\"item-row\">\r\n                <span>{{ $item->description }} <small>(x{{ $item->quantity }})</small></span>\r\n                <span>{{ format_currency($item->total) }}</span>\r\n            </div>\r\n            @endforeach\r\n            \r\n            <div class=\"total-row\">\r\n                GRAND TOTAL: {{ format_currency($total) }}\r\n            </div>\r\n            \r\n            <p style=\"margin-top: 20px; font-size: 12px; color: #888;\">\r\n                Penawaran ini valid sampai {{ $valid_until }}. Kami menunggu kabar baik dari Anda!\r\n            </p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(7,NULL,'Official Receipt','receipt',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; }\r\n        .receipt { border: 2px solid #000; padding: 20px; position: relative; }\r\n        .watermark { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) rotate(-30deg); font-size: 100px; color: rgba(0,0,0,0.05); z-index: -1; }\r\n        .header { text-align: center; border-bottom: 2px double #000; padding-bottom: 10px; margin-bottom: 20px; }\r\n        .row { display: flex; margin-bottom: 10px; }\r\n        .label { width: 150px; font-weight: bold; }\r\n        .value { flex: 1; border-bottom: 1px dotted #000; }\r\n        .amount { background: #eee; padding: 10px; font-weight: bold; font-size: 18px; display: inline-block; margin-top: 20px; border: 1px solid #000; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"receipt\">\r\n        <div class=\"watermark\">LUNAS</div>\r\n        <div class=\"header\">\r\n            <h2>KWITANSI PEMBAYARAN</h2>\r\n            <p>No: {{ $number }}</p>\r\n        </div>\r\n        \r\n        <div class=\"row\">\r\n            <span class=\"label\">Telah Terima Dari:</span>\r\n            <span class=\"value\">{{ $client->name }}</span>\r\n        </div>\r\n        <div class=\"row\">\r\n            <span class=\"label\">Uang Sejumlah:</span>\r\n            <span class=\"value\">{{ terbilang($amount) }} Rupiah</span>\r\n        </div>\r\n        <div class=\"row\">\r\n            <span class=\"label\">Untuk Pembayaran:</span>\r\n            <span class=\"value\">{{ $description }}</span>\r\n        </div>\r\n        \r\n        <table width=\"100%\" style=\"margin-top: 30px;\">\r\n            <tr>\r\n                <td valign=\"bottom\"><div class=\"amount\">{{ format_currency($amount) }}</div></td>\r\n                <td align=\"right\" valign=\"bottom\">\r\n                    <p>{{ $tenant->city }}, {{ $date }}</p>\r\n                    <br><br><br>\r\n                    <p>( {{ $tenant->company_name }} )</p>\r\n                </td>\r\n            </tr>\r\n        </table>\r\n    </div>\r\n</body>\r\n</html>',NULL,1,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(8,NULL,'Simple Receipt','receipt',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <style>\r\n        body { font-family: monospace; }\r\n        .box { border: 1px dashed #333; padding: 20px; max-width: 600px; margin: auto; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"box\">\r\n        <h2 style=\"text-align: center;\">TANDA TERIMA</h2>\r\n        <p>No: {{ $number }}</p>\r\n        <hr>\r\n        <p><strong>Diterima Dari:</strong> {{ $client->name }}</p>\r\n        <p><strong>Sejumlah:</strong> {{ format_currency($amount) }}</p>\r\n        <p><strong>Keterangan:</strong> {{ $description }}</p>\r\n        <hr>\r\n        <p style=\"text-align: right;\">{{ $date }}<br><br>TTD,<br>{{ $tenant->company_name }}</p>\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(9,NULL,'Modern Receipt','receipt',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <style>\r\n        body { font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif; background: #f8f9fa; padding: 20px; }\r\n        .card { background: white; border-radius: 15px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); overflow: hidden; max-width: 700px; margin: auto; }\r\n        .header { background: #4a90e2; color: white; padding: 20px; display: flex; justify-content: space-between; align-items: center; }\r\n        .body { padding: 40px; }\r\n        .field { margin-bottom: 20px; }\r\n        .label { font-size: 12px; color: #888; text-transform: uppercase; letter-spacing: 1px; }\r\n        .value { font-size: 18px; color: #333; border-bottom: 1px solid #eee; padding-bottom: 5px; }\r\n        .footer { background: #f1f3f5; padding: 20px; text-align: center; color: #888; font-size: 12px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"card\">\r\n        <div class=\"header\">\r\n            <h3>PAYMENT RECEIPT</h3>\r\n            <span>{{ $number }}</span>\r\n        </div>\r\n        <div class=\"body\">\r\n            <div class=\"field\">\r\n                <div class=\"label\">Received From</div>\r\n                <div class=\"value\">{{ $client->name }}</div>\r\n            </div>\r\n            <div class=\"field\">\r\n                <div class=\"label\">Amount</div>\r\n                <div class=\"value\" style=\"color: #4a90e2; font-weight: bold;\">{{ format_currency($amount) }}</div>\r\n            </div>\r\n            <div class=\"field\">\r\n                <div class=\"label\">For</div>\r\n                <div class=\"value\">{{ $description }}</div>\r\n            </div>\r\n            \r\n            <table width=\"100%\" style=\"margin-top: 40px;\">\r\n                <tr>\r\n                    <td>\r\n                        <div class=\"label\">Payment Method</div>\r\n                        <div>Transfer / Cash</div>\r\n                    </td>\r\n                    <td align=\"right\">\r\n                        <div class=\"label\">Authorized Signature</div>\r\n                        <br>\r\n                        <strong>{{ $tenant->company_name }}</strong>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </div>\r\n        <div class=\"footer\">\r\n            Thank you for your business!\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(10,NULL,'Standard Delivery Note','delivery_note',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <style>\r\n        body { font-family: Arial, sans-serif; }\r\n        .container { border: 1px solid #ccc; padding: 20px; }\r\n        .header center h1 { border-bottom: 2px solid #000; display: inline-block; }\r\n        table { width: 100%; border-collapse: collapse; margin-top: 20px; }\r\n        th, td { border: 1px solid #000; padding: 8px; }\r\n        .signatures { margin-top: 50px; display: flex; justify-content: space-between; }\r\n        .sig-box { text-align: center; width: 200px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <center>\r\n                <h1>SURAT JALAN</h1>\r\n                <p>No: {{ $number }}</p>\r\n            </center>\r\n        </div>\r\n        \r\n        <table style=\"border: none; margin-bottom: 20px;\">\r\n            <tr style=\"border: none;\">\r\n                <td style=\"border: none;\">\r\n                    <strong>Pengirim:</strong><br>\r\n                    {{ $tenant->company_name }}<br>\r\n                    {{ $tenant->address }}\r\n                </td>\r\n                <td style=\"border: none; text-align: right;\">\r\n                    <strong>Penerima:</strong><br>\r\n                    {{ $client->name }}<br>\r\n                    {{ $client->address }}\r\n                </td>\r\n            </tr>\r\n        </table>\r\n\r\n        <table>\r\n            <thead>\r\n                <tr>\r\n                    <th>No</th>\r\n                    <th>Nama Barang</th>\r\n                    <th>Qty</th>\r\n                    <th>Satuan</th>\r\n                    <th>Keterangan</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                @foreach($items as $i => $item)\r\n                <tr>\r\n                    <td align=\"center\">{{ $i+1 }}</td>\r\n                    <td>{{ $item->product_name }}</td>\r\n                    <td align=\"center\">{{ $item->quantity }}</td>\r\n                    <td align=\"center\">{{ $item->unit }}</td>\r\n                    <td>{{ $item->notes }}</td>\r\n                </tr>\r\n                @endforeach\r\n            </tbody>\r\n        </table>\r\n\r\n        <table style=\"border: none; margin-top: 50px;\">\r\n            <tr style=\"border: none;\">\r\n                <td style=\"border: none; text-align: center;\">\r\n                    Penerima,\r\n                    <br><br><br><br>\r\n                    (....................)\r\n                </td>\r\n                <td style=\"border: none; text-align: center;\">\r\n                    Pengirim,\r\n                    <br><br><br><br>\r\n                    (....................)\r\n                </td>\r\n            </tr>\r\n        </table>\r\n    </div>\r\n</body>\r\n</html>',NULL,1,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(11,NULL,'Logistic Style','delivery_note',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <style>\r\n        body { font-family: \'Courier New\', Courier, monospace; }\r\n        .wrap { border: 2px solid #000; padding: 15px; }\r\n        .row { display: flex; justify-content: space-between; border-bottom: 1px solid #000; padding-bottom: 10px; margin-bottom: 10px; }\r\n        .items-list { width: 100%; text-align: left; }\r\n        .items-list th { border-bottom: 2px solid #000; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"wrap\">\r\n        <h2>DELIVERY NOTE / SURAT JALAN</h2>\r\n        <div class=\"row\">\r\n            <div>\r\n                <strong>From:</strong> {{ $tenant->company_name }}\r\n            </div>\r\n            <div>\r\n                <strong>Date:</strong> {{ $date }}<br>\r\n                <strong>Doc No:</strong> {{ $number }}\r\n            </div>\r\n        </div>\r\n        <div style=\"margin-bottom: 20px;\">\r\n            <strong>Ship To:</strong><br>\r\n            {{ $client->name }}<br>\r\n            {{ $client->address }}\r\n        </div>\r\n        \r\n        <table class=\"items-list\">\r\n            <thead>\r\n                <tr>\r\n                    <th>ITEM</th>\r\n                    <th>QTY</th>\r\n                    <th>UNIT</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                @foreach($items as $item)\r\n                <tr>\r\n                    <td>{{ $item->product_name }}</td>\r\n                    <td>{{ $item->quantity }}</td>\r\n                    <td>{{ $item->unit }}</td>\r\n                </tr>\r\n                @endforeach\r\n            </tbody>\r\n        </table>\r\n        \r\n        <div style=\"margin-top: 40px;\">\r\n            <p><strong>Note:</strong> Barang telah diterima dengan baik dan cukup.</p>\r\n        </div>\r\n        \r\n        <table width=\"100%\" style=\"margin-top: 30px; text-align: center;\">\r\n            <tr>\r\n                <td>Received By</td>\r\n                <td>Driver</td>\r\n                <td>Authorized By</td>\r\n            </tr>\r\n        </table>\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(12,NULL,'Compact Delivery Note','delivery_note',NULL,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <style>\r\n        body { font-family: sans-serif; font-size: 12px; }\r\n        .header { background: #333; color: white; padding: 10px; text-align: center; font-weight: bold; }\r\n        .info { padding: 10px; display: flex; justify-content: space-between; background: #eee; }\r\n        .list { width: 100%; border-collapse: collapse; }\r\n        .list td, .list th { padding: 5px; border-bottom: 1px solid #ddd; }\r\n        .checkstroke { width: 20px; height: 20px; border: 1px solid #000; display: inline-block; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"header\">SURAT JALAN / {{ $number }}</div>\r\n    <div class=\"info\">\r\n        <div>{{ $tenant->company_name }}</div>\r\n        <div>{{ $date }}</div>\r\n    </div>\r\n    <div style=\"padding: 10px; border-bottom: 1px solid #ccc;\">\r\n        Tujuan: <strong>{{ $client->name }}</strong>\r\n    </div>\r\n    \r\n    <table class=\"list\">\r\n        <thead>\r\n            <tr>\r\n                <th width=\"30\">Check</th>\r\n                <th>Item</th>\r\n                <th>Qty</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            @foreach($items as $item)\r\n            <tr>\r\n                <td align=\"center\"><div class=\"checkstroke\"></div></td>\r\n                <td>{{ $item->product_name }}<br><small>{{ $item->notes }}</small></td>\r\n                <td align=\"center\">{{ $item->quantity }} {{ $item->unit }}</td>\r\n            </tr>\r\n            @endforeach\r\n        </tbody>\r\n    </table>\r\n    \r\n    <div style=\"margin-top: 30px; text-align: center;\">\r\n        <p>Silakan periksa barang sebelum tanda tangan.</p>\r\n        <br><br>\r\n        ( Tanda Tangan Penerima )\r\n    </div>\r\n</body>\r\n</html>',NULL,0,1,0,'2026-01-23 18:40:52','2026-01-23 18:40:52'),(14,5,'biru','invoice',NULL,'<!doctype html>\r\n<html lang=\"id\" class=\"h-full\">\r\n <head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Invoice Template</title>\r\n  <script src=\"https://cdn.tailwindcss.com/3.4.17\"></script>\r\n  <script src=\"https://cdn.jsdelivr.net/npm/lucide@0.263.0/dist/umd/lucide.min.js\"></script>\r\n  <script src=\"/_sdk/element_sdk.js\"></script>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&amp;family=DM+Serif+Display&amp;display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n        * { margin: 0; padding: 0; box-sizing: border-box; }\r\n\r\n        .invoice-page {\r\n            font-family: \'Plus Jakarta Sans\', sans-serif;\r\n            min-height: 100%;\r\n            padding: 40px 20px;\r\n        }\r\n\r\n        .invoice-box {\r\n            max-width: 800px;\r\n            margin: 0 auto;\r\n            border-radius: 20px;\r\n            overflow: hidden;\r\n            box-shadow: 0 25px 60px rgba(56, 147, 211, 0.12), 0 4px 16px rgba(0,0,0,0.04);\r\n            position: relative;\r\n        }\r\n\r\n        .invoice-box::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            top: 0; left: 0; right: 0;\r\n            height: 220px;\r\n            background: linear-gradient(135deg, #5bb5e8 0%, #87ceeb 40%, #a8ddf5 100%);\r\n            z-index: 0;\r\n        }\r\n\r\n        .header-section {\r\n            position: relative;\r\n            z-index: 1;\r\n            padding: 44px 48px 36px;\r\n        }\r\n\r\n        .header-top {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: flex-start;\r\n        }\r\n\r\n        .invoice-title {\r\n            font-family: \'DM Serif Display\', serif;\r\n            font-size: 42px;\r\n            letter-spacing: 4px;\r\n            color: #fff;\r\n            text-shadow: 0 2px 8px rgba(0,0,0,0.08);\r\n        }\r\n\r\n        .invoice-number {\r\n            font-size: 14px;\r\n            color: rgba(255,255,255,0.85);\r\n            margin-top: 6px;\r\n            font-weight: 500;\r\n            letter-spacing: 1px;\r\n        }\r\n\r\n        .company-info {\r\n            text-align: right;\r\n            color: #fff;\r\n            font-size: 14px;\r\n            line-height: 1.8;\r\n        }\r\n\r\n        .company-name {\r\n            font-weight: 700;\r\n            font-size: 16px;\r\n            margin-bottom: 2px;\r\n        }\r\n\r\n        .divider-wave {\r\n            position: relative;\r\n            z-index: 1;\r\n            margin-top: -30px;\r\n        }\r\n\r\n        .divider-wave svg {\r\n            display: block;\r\n            width: 100%;\r\n            height: 50px;\r\n        }\r\n\r\n        .content-section {\r\n            position: relative;\r\n            z-index: 1;\r\n            padding: 20px 48px 48px;\r\n        }\r\n\r\n        .bill-to-label {\r\n            font-size: 11px;\r\n            text-transform: uppercase;\r\n            letter-spacing: 2px;\r\n            font-weight: 700;\r\n            margin-bottom: 8px;\r\n        }\r\n\r\n        .client-name {\r\n            font-size: 18px;\r\n            font-weight: 700;\r\n            margin-bottom: 4px;\r\n        }\r\n\r\n        .client-address {\r\n            font-size: 14px;\r\n            line-height: 1.7;\r\n        }\r\n\r\n        .items-table {\r\n            width: 100%;\r\n            border-collapse: collapse;\r\n            margin-top: 36px;\r\n        }\r\n\r\n        .items-table thead th {\r\n            font-size: 11px;\r\n            text-transform: uppercase;\r\n            letter-spacing: 2px;\r\n            font-weight: 700;\r\n            padding: 14px 16px;\r\n            border-bottom: 2px solid;\r\n            text-align: left;\r\n        }\r\n\r\n        .items-table thead th:last-child,\r\n        .items-table thead th:nth-child(2) {\r\n            text-align: right;\r\n        }\r\n\r\n        .items-table tbody td {\r\n            padding: 18px 16px;\r\n            font-size: 14px;\r\n            border-bottom: 1px solid #e8f2fa;\r\n        }\r\n\r\n        .items-table tbody td:last-child,\r\n        .items-table tbody td:nth-child(2) {\r\n            text-align: right;\r\n            font-weight: 500;\r\n        }\r\n\r\n        .items-table tbody tr:last-child td {\r\n            border-bottom: none;\r\n        }\r\n\r\n        .total-section {\r\n            margin-top: 32px;\r\n            display: flex;\r\n            justify-content: flex-end;\r\n        }\r\n\r\n        .total-card {\r\n            border-radius: 14px;\r\n            padding: 24px 36px;\r\n            text-align: right;\r\n            min-width: 280px;\r\n        }\r\n\r\n        .total-label-text {\r\n            font-size: 12px;\r\n            text-transform: uppercase;\r\n            letter-spacing: 2px;\r\n            font-weight: 600;\r\n            margin-bottom: 6px;\r\n        }\r\n\r\n        .total-amount {\r\n            font-family: \'DM Serif Display\', serif;\r\n            font-size: 32px;\r\n        }\r\n\r\n        .footer-section {\r\n            margin-top: 40px;\r\n            padding-top: 24px;\r\n            border-top: 1px dashed #c8e2f5;\r\n            text-align: center;\r\n            font-size: 12px;\r\n            line-height: 1.8;\r\n        }\r\n\r\n        /* Blade template overlay */\r\n        .blade-tag {\r\n            font-family: \'Plus Jakarta Sans\', monospace;\r\n            background: rgba(91, 181, 232, 0.1);\r\n            border: 1px dashed rgba(91, 181, 232, 0.4);\r\n            border-radius: 4px;\r\n            padding: 1px 6px;\r\n            font-size: 12px;\r\n            color: #3a8bc5;\r\n        }\r\n\r\n        .blade-block {\r\n            background: rgba(91, 181, 232, 0.05);\r\n            border-left: 3px solid #87ceeb;\r\n            padding: 14px 16px;\r\n            border-radius: 0 6px 6px 0;\r\n            margin: 4px 0;\r\n        }\r\n\r\n        @media (max-width: 640px) {\r\n            .invoice-page { padding: 16px 8px; }\r\n            .header-section, .content-section { padding-left: 24px; padding-right: 24px; }\r\n            .invoice-title { font-size: 28px; letter-spacing: 2px; }\r\n            .header-top { flex-direction: column; gap: 16px; }\r\n            .company-info { text-align: left; }\r\n            .total-card { min-width: auto; width: 100%; }\r\n            .total-amount { font-size: 24px; }\r\n        }\r\n    </style>\r\n  <style>body { box-sizing: border-box; }</style>\r\n  <script src=\"/_sdk/data_sdk.js\" type=\"text/javascript\"></script>\r\n </head>\r\n <body class=\"h-full\">\r\n  <div class=\"invoice-page\" id=\"invoicePage\" style=\"background: #f0f7fc;\">\r\n   <div class=\"invoice-box\" style=\"background: #ffffff;\"><!-- Header -->\r\n    <div class=\"header-section\">\r\n     <div class=\"header-top\">\r\n      <div>\r\n       <h1 class=\"invoice-title\" id=\"invoiceTitle\">INVOICE</h1>\r\n       <p class=\"invoice-number\">#<span class=\"blade-tag\">{{ $number }}</span></p>\r\n      </div>\r\n      <div class=\"company-info\">\r\n       <div class=\"company-name\">\r\n        <span class=\"blade-tag\">{{ $tenant-&gt;company_name }}</span>\r\n       </div>\r\n       <div>\r\n        <span class=\"blade-tag\">{{ $tenant-&gt;email }}</span>\r\n       </div>\r\n      </div>\r\n     </div>\r\n    </div><!-- Wave Divider -->\r\n    <div class=\"divider-wave\">\r\n     <svg viewbox=\"0 0 800 50\" preserveaspectratio=\"none\"><path d=\"M0,20 C200,50 400,0 600,30 C700,45 750,15 800,25 L800,50 L0,50 Z\" fill=\"#ffffff\" />\r\n     </svg>\r\n    </div><!-- Content -->\r\n    <div class=\"content-section\">\r\n     <div>\r\n      <p class=\"bill-to-label\" id=\"billToLabel\" style=\"color: #5bb5e8;\">Ditujukan Kepada:</p>\r\n      <p class=\"client-name\" style=\"color: #1e3a5f;\"><span class=\"blade-tag\">{{ $client-&gt;name }}</span></p>\r\n      <p class=\"client-address\" style=\"color: #6a8caa;\"><span class=\"blade-tag\">{{ $client-&gt;address }}</span></p>\r\n     </div><!-- Items Table -->\r\n     <table class=\"items-table\">\r\n      <thead>\r\n       <tr>\r\n        <th style=\"color: #5bb5e8; border-color: #87ceeb;\">Deskripsi</th>\r\n        <th style=\"color: #5bb5e8; border-color: #87ceeb;\">Jumlah</th>\r\n        <th style=\"color: #5bb5e8; border-color: #87ceeb;\">Harga</th>\r\n       </tr>\r\n      </thead>\r\n      <tbody id=\"itemsBody\" style=\"color: #2c4a6b;\">\r\n       <tr class=\"blade-block\">\r\n        <td colspan=\"3\" style=\"text-align: center; color: #3a8bc5; font-size: 12px; padding: 10px;\">@foreach($items as $item)</td>\r\n       </tr>\r\n       <tr>\r\n        <td><span class=\"blade-tag\">{{ $item-&gt;description }}</span></td>\r\n        <td><span class=\"blade-tag\">{{ $item-&gt;quantity }}</span></td>\r\n        <td><span class=\"blade-tag\">{{ format_currency($item-&gt;total) }}</span></td>\r\n       </tr>\r\n       <tr class=\"blade-block\">\r\n        <td colspan=\"3\" style=\"text-align: center; color: #3a8bc5; font-size: 12px; padding: 10px;\">@endforeach</td>\r\n       </tr>\r\n      </tbody>\r\n     </table><!-- Total -->\r\n     <div class=\"total-section\">\r\n      <div class=\"total-card\" style=\"background: linear-gradient(135deg, #e8f4fd 0%, #d4ecf9 100%);\">\r\n       <p class=\"total-label-text\" id=\"totalLabel\" style=\"color: #5bb5e8;\">Total Pembayaran:</p>\r\n       <p class=\"total-amount\" style=\"color: #1e3a5f;\"><span class=\"blade-tag\">{{ format_currency($total) }}</span></p>\r\n      </div>\r\n     </div><!-- Footer -->\r\n     <div class=\"footer-section\" style=\"color: #8badc5;\">\r\n      <p>Terima kasih atas kepercayaan Anda 💙</p>\r\n      <p style=\"margin-top: 4px;\">Invoice ini dibuat secara otomatis dan sah tanpa tanda tangan.</p>\r\n     </div>\r\n    </div>\r\n   </div>\r\n  </div>\r\n  <script>\r\n        const defaultConfig = {\r\n            background_color: \'#f0f7fc\',\r\n            surface_color: \'#ffffff\',\r\n            text_color: \'#1e3a5f\',\r\n            primary_action: \'#5bb5e8\',\r\n            secondary_action: \'#87ceeb\',\r\n            font_family: \'Plus Jakarta Sans\',\r\n            font_size: 14,\r\n            invoice_title: \'INVOICE\',\r\n            bill_to_label: \'Ditujukan Kepada:\',\r\n            total_label: \'Total Pembayaran:\'\r\n        };\r\n\r\n        function applyConfig(config) {\r\n            const bg = config.background_color || defaultConfig.background_color;\r\n            const surface = config.surface_color || defaultConfig.surface_color;\r\n            const text = config.text_color || defaultConfig.text_color;\r\n            const primary = config.primary_action || defaultConfig.primary_action;\r\n            const secondary = config.secondary_action || defaultConfig.secondary_action;\r\n            const font = config.font_family || defaultConfig.font_family;\r\n            const baseSize = config.font_size || defaultConfig.font_size;\r\n\r\n            const page = document.getElementById(\'invoicePage\');\r\n            page.style.background = bg;\r\n\r\n            const box = page.querySelector(\'.invoice-box\');\r\n            box.style.background = surface;\r\n\r\n            // Gradient header\r\n            box.querySelector(\'.invoice-box\')?.style;\r\n            const beforeStyle = document.getElementById(\'dynamicStyle\');\r\n            if (beforeStyle) {\r\n                beforeStyle.textContent = `.invoice-box::before { background: linear-gradient(135deg, ${primary} 0%, ${secondary} 40%, ${lighten(secondary, 20)} 100%) !important; }`;\r\n            }\r\n\r\n            // Title\r\n            const titleEl = document.getElementById(\'invoiceTitle\');\r\n            titleEl.textContent = config.invoice_title || defaultConfig.invoice_title;\r\n            titleEl.style.fontFamily = `\'DM Serif Display\', ${font}, serif`;\r\n            titleEl.style.fontSize = `${baseSize * 3}px`;\r\n\r\n            // Bill to\r\n            const billTo = document.getElementById(\'billToLabel\');\r\n            billTo.textContent = config.bill_to_label || defaultConfig.bill_to_label;\r\n            billTo.style.color = primary;\r\n            billTo.style.fontSize = `${baseSize * 0.78}px`;\r\n\r\n            // Total\r\n            const totalLabel = document.getElementById(\'totalLabel\');\r\n            totalLabel.textContent = config.total_label || defaultConfig.total_label;\r\n            totalLabel.style.color = primary;\r\n            totalLabel.style.fontSize = `${baseSize * 0.85}px`;\r\n\r\n            // Total card bg\r\n            const totalCard = document.querySelector(\'.total-card\');\r\n            totalCard.style.background = `linear-gradient(135deg, ${hexToRgba(primary, 0.1)} 0%, ${hexToRgba(secondary, 0.15)} 100%)`;\r\n\r\n            // Total amount\r\n            const totalAmount = document.querySelector(\'.total-amount\');\r\n            totalAmount.style.color = text;\r\n            totalAmount.style.fontSize = `${baseSize * 2.3}px`;\r\n            totalAmount.style.fontFamily = `\'DM Serif Display\', ${font}, serif`;\r\n\r\n            // Client text\r\n            document.querySelector(\'.client-name\').style.color = text;\r\n            document.querySelector(\'.client-name\').style.fontSize = `${baseSize * 1.28}px`;\r\n            document.querySelector(\'.client-address\').style.color = hexToRgba(text, 0.6);\r\n            document.querySelector(\'.client-address\').style.fontSize = `${baseSize}px`;\r\n\r\n            // Table headers\r\n            document.querySelectorAll(\'.items-table thead th\').forEach(th => {\r\n                th.style.color = primary;\r\n                th.style.borderColor = secondary;\r\n                th.style.fontSize = `${baseSize * 0.78}px`;\r\n            });\r\n\r\n            // Table body\r\n            document.querySelector(\'#itemsBody\').style.color = text;\r\n            document.querySelectorAll(\'.items-table tbody td\').forEach(td => {\r\n                td.style.fontSize = `${baseSize}px`;\r\n            });\r\n\r\n            // Company info\r\n            document.querySelector(\'.company-name\').style.fontSize = `${baseSize * 1.14}px`;\r\n\r\n            // Invoice number\r\n            document.querySelector(\'.invoice-number\').style.fontSize = `${baseSize}px`;\r\n\r\n            // Footer\r\n            document.querySelector(\'.footer-section\').style.color = hexToRgba(text, 0.5);\r\n            document.querySelector(\'.footer-section\').style.borderColor = hexToRgba(secondary, 0.4);\r\n            document.querySelector(\'.footer-section\').style.fontSize = `${baseSize * 0.85}px`;\r\n\r\n            // Wave fill\r\n            document.querySelector(\'.divider-wave path\').setAttribute(\'fill\', surface);\r\n\r\n            // Font family for body\r\n            page.style.fontFamily = `\'${font}\', sans-serif`;\r\n\r\n            // Blade tags\r\n            document.querySelectorAll(\'.blade-tag\').forEach(el => {\r\n                el.style.color = primary;\r\n                el.style.background = hexToRgba(primary, 0.1);\r\n                el.style.borderColor = hexToRgba(primary, 0.4);\r\n            });\r\n            document.querySelectorAll(\'.blade-block\').forEach(el => {\r\n                el.style.background = hexToRgba(primary, 0.05);\r\n                el.style.borderLeftColor = secondary;\r\n            });\r\n        }\r\n\r\n        function hexToRgba(hex, alpha) {\r\n            hex = hex.replace(\'#\', \'\');\r\n            const r = parseInt(hex.substring(0, 2), 16);\r\n            const g = parseInt(hex.substring(2, 4), 16);\r\n            const b = parseInt(hex.substring(4, 6), 16);\r\n            return `rgba(${r},${g},${b},${alpha})`;\r\n        }\r\n\r\n        function lighten(hex, percent) {\r\n            hex = hex.replace(\'#\', \'\');\r\n            let r = parseInt(hex.substring(0, 2), 16);\r\n            let g = parseInt(hex.substring(2, 4), 16);\r\n            let b = parseInt(hex.substring(4, 6), 16);\r\n            r = Math.min(255, r + Math.round((255 - r) * percent / 100));\r\n            g = Math.min(255, g + Math.round((255 - g) * percent / 100));\r\n            b = Math.min(255, b + Math.round((255 - b) * percent / 100));\r\n            return `#${r.toString(16).padStart(2,\'0\')}${g.toString(16).padStart(2,\'0\')}${b.toString(16).padStart(2,\'0\')}`;\r\n        }\r\n\r\n        // Add dynamic style element for pseudo-element\r\n        const styleEl = document.createElement(\'style\');\r\n        styleEl.id = \'dynamicStyle\';\r\n        document.head.appendChild(styleEl);\r\n\r\n        // Init SDK\r\n        window.elementSdk.init({\r\n            defaultConfig,\r\n            onConfigChange: async (config) => { applyConfig(config); },\r\n            mapToCapabilities: (config) => ({\r\n                recolorables: [\r\n                    { get: () => config.background_color || defaultConfig.background_color, set: (v) => { config.background_color = v; window.elementSdk.setConfig({ background_color: v }); } },\r\n                    { get: () => config.surface_color || defaultConfig.surface_color, set: (v) => { config.surface_color = v; window.elementSdk.setConfig({ surface_color: v }); } },\r\n                    { get: () => config.text_color || defaultConfig.text_color, set: (v) => { config.text_color = v; window.elementSdk.setConfig({ text_color: v }); } },\r\n                    { get: () => config.primary_action || defaultConfig.primary_action, set: (v) => { config.primary_action = v; window.elementSdk.setConfig({ primary_action: v }); } },\r\n                    { get: () => config.secondary_action || defaultConfig.secondary_action, set: (v) => { config.secondary_action = v; window.elementSdk.setConfig({ secondary_action: v }); } }\r\n                ],\r\n                borderables: [],\r\n                fontEditable: {\r\n                    get: () => config.font_family || defaultConfig.font_family,\r\n                    set: (v) => { config.font_family = v; window.elementSdk.setConfig({ font_family: v }); }\r\n                },\r\n                fontSizeable: {\r\n                    get: () => config.font_size || defaultConfig.font_size,\r\n                    set: (v) => { config.font_size = v; window.elementSdk.setConfig({ font_size: v }); }\r\n                }\r\n            }),\r\n            mapToEditPanelValues: (config) => new Map([\r\n                [\'invoice_title\', config.invoice_title || defaultConfig.invoice_title],\r\n                [\'bill_to_label\', config.bill_to_label || defaultConfig.bill_to_label],\r\n                [\'total_label\', config.total_label || defaultConfig.total_label]\r\n            ])\r\n        });\r\n\r\n        lucide.createIcons();\r\n    </script>\r\n <script>(function(){function c(){var b=a.contentDocument||a.contentWindow.document;if(b){var d=b.createElement(\'script\');d.innerHTML=\"window.__CF$cv$params={r:\'9f3bada005b4a620\',t:\'MTc3NzQzODE0Ni4wMDAwMDA=\'};var a=document.createElement(\'script\');a.nonce=\'\';a.src=\'/cdn-cgi/challenge-platform/scripts/jsd/main.js\';document.getElementsByTagName(\'head\')[0].appendChild(a);\";b.getElementsByTagName(\'head\')[0].appendChild(d)}}if(document.body){var a=document.createElement(\'iframe\');a.height=1;a.width=1;a.style.position=\'absolute\';a.style.top=0;a.style.left=0;a.style.border=\'none\';a.style.visibility=\'hidden\';document.body.appendChild(a);if(\'loading\'!==document.readyState)c();else if(window.addEventListener)document.addEventListener(\'DOMContentLoaded\',c);else{var e=document.onreadystatechange||function(){};document.onreadystatechange=function(b){e(b);\'loading\'!==document.readyState&&(document.onreadystatechange=e,c())}}}})();</script></body>\r\n</html>',NULL,0,0,0,'2026-04-28 21:49:27','2026-04-28 21:49:27');
